select throws_ok(format($$select public.save_sales_tracking_draft('1a000000-0000-4000-8000-000000000002','3a000000-0000-4000-8000-000000000001',0,'closing_shift','[{"entry_date":"%s","actual_cash":30}]','[{"entry_date":"%s","remaining_cash":0}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'40001','sales tracking changed','stale Closing Shift save conflicts');
