select throws_ok($$delete from public.sales_tracking_sales_rows where report_id=(select id from public.sales_tracking_reports where branch_id='3a000000-0000-4000-8000-000000000001')and period_entry_id is not null$$,'55000','saved sales tracking data is immutable','saved Sales row cannot be deleted directly');
select throws_ok($$delete from public.sales_tracking_cash_rows where report_id=(select id from public.sales_tracking_reports where branch_id='3a000000-0000-4000-8000-000000000001')and period_entry_id is not null$$,'55000','saved sales tracking data is immutable','saved Cash row cannot be deleted directly');
