select ok(not has_table_privilege('authenticated','public.sales_tracking_reports','insert,update,delete,truncate')and not has_table_privilege('authenticated','public.sales_tracking_period_entries','insert,update,delete,truncate')and not has_table_privilege('authenticated','public.sales_tracking_sales_rows','insert,update,delete,truncate')and not has_table_privilege('authenticated','public.sales_tracking_cash_rows','insert,update,delete,truncate'),'authenticated has no direct Sales mutation or truncate path');
